-- 原来 14 个音色的 ID（TTS_DoubaoSeedTTS2_01 到 _14）保持不变，新音色从 _015 开始编号。
-- scene 是控制台给的第一个场景；一个音色可能属于多个场景，这里只放主场景。
-- 官方音色名最长 21 个字（Kevin McCallister 2.0），原来的 varchar(20) 不够。
ALTER TABLE `ai_tts_voice` MODIFY COLUMN `name` varchar(64) DEFAULT NULL COMMENT '音色名称';
delete from `ai_tts_voice` where tts_model_id = 'TTS_DoubaoSeedTTS2';
